typedef float rational_t;
typedef int axis_id_t;

enum PS2_Axes
{
  JOY_PS2_DX,
  JOY_PS2_DY,
  JOY_PS2_X,
  JOY_PS2_Y,
  JOY_PS2_LX,
  JOY_PS2_LY,
  JOY_PS2_BTNL3,
  JOY_PS2_RX,
  JOY_PS2_RY,
  JOY_PS2_BTNR3,
  JOY_PS2_BTNX,
  JOY_PS2_BTNO,
  JOY_PS2_DUMMMY1,
  JOY_PS2_BTNSQ,
  JOY_PS2_BTNTR,
  JOY_PS2_DUMMMY2,
  JOY_PS2_BTNL1,
  JOY_PS2_BTNR1,
  JOY_PS2_BTNL2,
  JOY_PS2_BTNR2,
  JOY_PS2_START,
  JOY_PS2_SELECT,
  JOY_PS2_DISCONNECT,
  JOY_PS2_NUM_AXES
};

#define assert(x) ((void)0)

class AISurferController
{
  char padding[0x9c];
  float X, Y, XRight, YRight;
  bool ButtonX, ButtonO, ButtonSq, ButtonTr;
  bool ButtonL1, ButtonL2, ButtonL3, ButtonR1, ButtonR2, ButtonR3;
  bool ButtonSelect, ButtonStart;

public:
  rational_t get_axis_state(axis_id_t axis, int control_axis) const;
};

rational_t AISurferController::get_axis_state(axis_id_t axis, int control_axis ) const
{
  switch (axis) 
  {
    case JOY_PS2_X: // left analog horiz
      return X;

    case JOY_PS2_Y: // left analog vert
      return Y;

    case JOY_PS2_DX: // just Dpad
      if (X < 0)
      {
          return -1.0f;
      }
      else if (X > 0)
      {
          return 1.0f;
      }
      return 0.0f;

    case JOY_PS2_DY: // just Dpad -1 = up
      if (Y < 0)
      {
          return -1.0f;  //up
      }
      else if (Y > 0)
      {
          return 1.0f;
      }
      return 0.0f;

    case JOY_PS2_LX: //  - 1 = left
      return X;
    case JOY_PS2_LY: // -1 = up
      return Y;
    case JOY_PS2_RX: 
      return XRight;
    case JOY_PS2_RY: 
      return YRight;

    case JOY_PS2_BTNL3: // L3
      return ButtonL3;
    case JOY_PS2_BTNR3: 
      return ButtonR3;
    case JOY_PS2_BTNX:  // A (ps2 x)
      return ButtonX;
    case JOY_PS2_BTNO:  // B (ps2 o)
        return ButtonO;
    case JOY_PS2_BTNSQ: // X (ps2 sq)
        return ButtonSq;
    case JOY_PS2_BTNTR: // Y (ps2 tr)
        return ButtonTr;

    case JOY_PS2_BTNR1: // C (ps2 R1)
        return ButtonR1;
    case JOY_PS2_BTNR2: // R (ps2 R2)
        return ButtonR2;

    case JOY_PS2_BTNL1: // Z (ps2 L1)
        return ButtonL1;
    case JOY_PS2_BTNL2: // L (ps2 L2)
        return ButtonL2;


    case JOY_PS2_START: // Start
      return ButtonStart;
    case JOY_PS2_SELECT:
      return ButtonSelect;

    default:
      assert("ps2_joypad_device::get_axis_state illegal axis queried." == 0);
      return 0.0f;

  }
}
